    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> deg(n);
    vector<char> alive(n, 1);
    for (int i = 0; i < n; i++) deg[i] = g[i].size();
    long long remaining = n - 1; // edges still in the tree
    // phase 1: repeatedly strip leaves without passengers
    deque<int> q;
    for (int i = 0; i < n; i++) if (deg[i] <= 1 && flag[i] == 0) q.push_back(i);
    while (!q.empty()) {
        int v = q.front();
        q.pop_front();
        if (!alive[v]) continue;
        alive[v] = 0;
        for (int w : g[v]) {
            if (!alive[w]) continue;
            remaining--;
            deg[w]--;
            if (deg[w] <= 1 && flag[w] == 0) q.push_back(w);
        }
    }
    // phase 2: strip two whole layers of leaves (picked up from two edges away)
    for (int i = 0; i < n; i++) if (alive[i] && deg[i] <= 1) q.push_back(i);
    for (int round = 0; round < 2; round++) {
        size_t cnt = q.size();
