import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        int[] flag = new int[n];
        for (int i = 0; i < n; i++) flag[i] = nextInt();
        int[] eu = new int[n - 1], ev = new int[n - 1], start = new int[n + 1];
        for (int i = 0; i < n - 1; i++) { eu[i] = nextInt(); ev[i] = nextInt(); start[eu[i] + 1]++; start[ev[i] + 1]++; }
        for (int i = 0; i < n; i++) start[i + 1] += start[i];
        int[] adj = new int[2 * (n - 1)], fill = Arrays.copyOf(start, n);
        for (int i = 0; i < n - 1; i++) { adj[fill[eu[i]]++] = ev[i]; adj[fill[ev[i]]++] = eu[i]; }
        int[] deg = new int[n];
        boolean[] alive = new boolean[n];
        for (int i = 0; i < n; i++) { deg[i] = start[i + 1] - start[i]; alive[i] = true; }
        long remaining = n - 1; // edges still in the tree
        // phase 1: repeatedly strip leaves without passengers (each node enters at most deg+1 times)
        int[] q = new int[3 * n + 3];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) if (deg[i] <= 1 && flag[i] == 0) q[tail++] = i;
        while (head < tail) {
            int v = q[head++];
            if (!alive[v]) continue;
            alive[v] = false;
            for (int e = start[v]; e < start[v + 1]; e++) {
                int w = adj[e];
                if (!alive[w]) continue;
                remaining--;
                deg[w]--;
                if (deg[w] <= 1 && flag[w] == 0) q[tail++] = w;
            }
        }
        // phase 2: strip two whole layers of leaves (picked up from two edges away)
        head = tail = 0;
        for (int i = 0; i < n; i++) if (alive[i] && deg[i] <= 1) q[tail++] = i;
        for (int round = 0; round < 2; round++) {
            int end = tail;
            while (head < end) {
                int v = q[head++];
                alive[v] = false;
                for (int e = start[v]; e < start[v + 1]; e++) {
                    int w = adj[e];
                    if (!alive[w]) continue;
                    remaining--;
                    deg[w]--;
                    if (deg[w] == 1) q[tail++] = w;
                }
            }
        }
        System.out.println(2 * Math.max(0, remaining));
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	flag := make([]int, n)
	for i := range flag {
		flag[i] = readInt()
	}
	g := make([][]int, n)
	for i := 0; i < n-1; i++ {
		a, b := readInt(), readInt()
		g[a] = append(g[a], b)
		g[b] = append(g[b], a)
	}
	deg := make([]int, n)
	alive := make([]bool, n)
	for i := range g {
		deg[i] = len(g[i])
		alive[i] = true
	}
	remaining := n - 1 // edges still in the tree
	// phase 1: repeatedly strip leaves without passengers
	var q []int
	for i := 0; i < n; i++ {
		if deg[i] <= 1 && flag[i] == 0 {
			q = append(q, i)
		}
	}
	for head := 0; head < len(q); head++ {
		v := q[head]
		if !alive[v] {
			continue
		}
		alive[v] = false
		for _, w := range g[v] {
			if !alive[w] {
				continue
			}
			remaining--
			deg[w]--
			if deg[w] <= 1 && flag[w] == 0 {
				q = append(q, w)
			}
		}
	}
	// phase 2: strip two whole layers of leaves (picked up from two edges away)
	q = q[:0]
	for i := 0; i < n; i++ {
		if alive[i] && deg[i] <= 1 {
			q = append(q, i)
		}
	}
	for round := 0; round < 2; round++ {
		var next []int
		for _, v := range q {
			alive[v] = false
			for _, w := range g[v] {
				if !alive[w] {
					continue
				}
				remaining--
				deg[w]--
				if deg[w] == 1 {
					next = append(next, w)
				}
			}
		}
		q = next
	}
	fmt.Println(2 * max(0, remaining))
}
